import { z } from "zod";

(() => {
  const { query } = defineParams(z.object({ query: z.string().min(1).describe("ニュースの検索語") }));
  const box = document.querySelector<HTMLInputElement>("#q");
  if (box !== null) box.value = query;
  document.querySelector<HTMLButtonElement>("#search")?.click();
  globalThis.__bh.log.info("検索語を入れて押した", { query });
  globalThis.__bh.report({
    query,
    token: globalThis.__bh.secrets.api_token === undefined ? "none" : "given",
    login: globalThis.__bh.secrets.login === undefined ? "none" : "given",
  });
})();

